INSERT INTO nu_BGP_3492496584436433866  (product, k_count) select (CASE WHEN r1.product NOT NULL THEN r1.product ELSE r2.product END) as product, coalesce(r1.k_count, 0) + coalesce(r2.k_count, 0) as k_count from BGP_3492496584436433866 AS r1 FULL OUTER JOIN delta_BGP_3492496584436433866 AS r2 ON r1.product = r2.product WHERE (coalesce(r1.k_count, 0) + coalesce(r2.k_count, 0)) > 0;